function normalizeUser(x){let ids=x.warehouses||x.warehouseIds||[];if(typeof ids==='string'){try{ids=JSON.parse(ids)}catch(e){ids=ids.split(',').map(v=>v.trim()).filter(Boolean)}}return {...x,warehouses:Array.isArray(ids)?ids:[]}}
function displayDate(value){if(!value)return '—';if(/T|Z/.test(String(value))){const d=new Date(value);if(!Number.isNaN(d.getTime()))return d.toLocaleString('ru-RU',{dateStyle:'short',timeStyle:'short'})}return String(value).replace(',', '')}
function normalizeSheetData(x){const warehouses=x.Warehouses||[],accounts=x.Accounts||[],suppliers=x.Suppliers||[],warehouseName=v=>warehouses.find(w=>String(w.id)===String(v))?.name||v||'',accountName=v=>accounts.find(a=>String(a.id)===String(v))?.name||v||'',supplierName=v=>suppliers.find(s=>String(s.id)===String(v))?.name||v||'',deliveryItems=x.DeliveryItems||[],writeoffItems=x.WriteoffItems||[],itemsFor=(rows,idKey,id)=>rows.filter(i=>String(i[idKey])===String(id)).map(i=>({...i,qty:+i.qty||0,cost:+i.cost||0,markup:+i.markup||0,retailTotal:+i.retailTotal||0}));return {...x,Accounts:accounts.map(a=>({...a,balance:+a.balance||0,initial:+a.initial||0})),Sellers:(x.Sellers||[]).map(normalizeUser),Sales:(x.Sales||[]).map(s=>({...s,qty:+s.qty||0,markup:+s.markup||0,unitPrice:+s.unitPrice||0,total:+s.total||0,profit:+s.profit||0,warehouse:warehouseName(s.warehouseId)})),Deliveries:(x.Deliveries||[]).map(d=>({...d,date:displayDate(d.date),supplier:d.supplier||supplierName(d.supplierId),warehouse:d.warehouse||warehouseName(d.warehouseId),account:d.account||accountName(d.accountId),paid:+d.paid||0,total:+d.total||0,items:d.items||itemsFor(deliveryItems,'deliveryId',d.id)})),Writeoffs:(x.Writeoffs||[]).map(w=>({...w,date:displayDate(w.date),warehouse:w.warehouse||warehouseName(w.warehouseId),account:w.account||accountName(w.accountId),total:+w.total||0,items:w.items||itemsFor(writeoffItems,'writeoffId',w.id)}))}}
function inventoryFromData(x){
  const batches=[];
  const findBatch=(name,pack,warehouse,deliveryId)=>{
    if(deliveryId){
      const exact=batches.find(b=>b.name===name&&String(b.pack||'')===String(pack||'')&&b.warehouse===warehouse&&String(b.deliveryId||'')===String(deliveryId));
      if(exact)return exact;
    }
    return batches.find(b=>b.name===name&&String(b.pack||'')===String(pack||'')&&b.warehouse===warehouse&&b.stock>0.000001);
  };
  const deliveries=(x.Deliveries||[]).slice().sort((a,b)=>(+new Date(a.date||0))-(+new Date(b.date||0)));
  deliveries.forEach(d=>(d.items||[]).forEach(i=>{
    if(!i?.name)return;
    const qty=+i.qty||0;
    if(!qty)return;
    batches.push({name:i.name,pack:i.pack||'',stock:qty,cost:+i.cost||0,markup:+i.markup||0,retailTotal:+i.retailTotal||0,warehouse:d.warehouse||'',deliveryId:d.id||'',deliveryDate:d.date||'',supplier:d.supplier||'',account:d.account||''});
  }));
  (x.Sales||[]).forEach(s=>{if(!s.productName)return;const b=findBatch(s.productName,s.pack||'',s.warehouse,s.deliveryId);if(b)b.stock-=(+s.qty||0)});
  (x.Writeoffs||[]).forEach(w=>(w.items||[]).forEach(i=>{if(!i?.name)return;const b=findBatch(i.name,i.pack||'',w.warehouse,i.deliveryId);if(b)b.stock-=(+i.qty||0)}));
  return batches.filter(b=>b.stock>0.000001);
}
function ensureCatalog(){
  if(Array.isArray(db.catalog))return;
  const seen=new Map();
  const push=(name,pack)=>{const n=String(name||'').trim();if(!n)return;const p=String(pack||'').trim();const key=n+'|'+p;if(seen.has(key))return;seen.set(key,{name:n,pack:p})};
  (db.deliveries||[]).forEach(d=>(d.items||[]).forEach(i=>push(i.name,i.pack)));
  (db.writeoffs||[]).forEach(w=>(w.items||[]).forEach(i=>push(i.name,i.pack)));
  (db.sales||[]).forEach(s=>push(s.productName,s.pack));
  (db.products||[]).forEach(p=>push(p.name,p.pack));
  db.catalog=[...seen.values()];
}
function catalogAdd(name,pack){
  const n=String(name||'').trim();if(!n)return;
  const p=String(pack||'').trim();
  if(!Array.isArray(db.catalog))db.catalog=[];
  if(!db.catalog.some(x=>x.name===n&&String(x.pack||'')===p))db.catalog.push({name:n,pack:p});
}
function catalogNames(){ensureCatalog();return [...new Set(db.catalog.map(x=>x.name))].sort((a,b)=>a.localeCompare(b,'ru'))}
function catalogPacks(name){
  ensureCatalog();
  const q=String(name||'').toLocaleLowerCase().trim();
  const matching=[],others=[];
  db.catalog.forEach(x=>{
    const pack=x.pack;
    if(!pack)return;
    const nm=String(x.name||'').toLocaleLowerCase();
    const hit=q&&(nm===q||nm.startsWith(q));
    (hit?matching:others).push(pack);
  });
  return [...new Set([...matching,...others])];
}
function sourceItem(name,pack,warehouse){const found=(db.deliveries||[]).flatMap(d=>(d.items||[]).map(i=>({...i,warehouse:d.warehouse}))).find(i=>i.name===name&&(!pack||i.pack===pack)&&(!warehouse||i.warehouse===warehouse));return found||null}
