function toast(x){const t=el('#toast');if(t){t.textContent=x;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}}
async function api(action,entity,data){if(!API_URL)return {ok:false,error:'API_URL не настроен'};try{const r=await fetch(API_URL,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,entity,data,token:session?.token||''})}),result=await r.json();if(!result.ok&&/сессия|session/i.test(result.error||'')){session=null;sessionStorage.removeItem('qini-session');toast('Сессия истекла. Войдите снова.');setTimeout(()=>render(),900)}return result}catch(e){return {ok:false,error:e.message}}}
function login(){document.querySelector('#app').innerHTML=`<div class="login-page"><div class="login-card"><div class="brand login-brand"><div class="brand-mark">Q</div><div class="brand-text">qini</div></div><div class="login-kicker">УЧЁТ ПОСТАВОК</div><h1>С возвращением</h1><p>Войдите в рабочее пространство Qini</p><form id="loginForm"><label class="label">Логин</label><input class="input" name="login" autocomplete="username" placeholder="Введите логин" required><label class="label">Пароль</label><input class="input" type="password" name="password" autocomplete="current-password" placeholder="Введите пароль" required><button class="btn btn-primary login-button">Войти в Qini</button><div class="login-hint">Данные проверяются сервером Apps Script</div><div id="loginError" class="login-error"></div></form></div></div>`;el('#loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),l=f.get('login'),p=f.get('password');if(API_URL){const r=await api('login',null,{login:l,password:p});if(r.ok){session=r.session;sessionStorage.setItem('qini-session',JSON.stringify(session));render();await sync()}else el('#loginError').textContent=r.error||'Неверный логин или пароль'}else{if(l===db.auth.login&&p===db.auth.password)session={role:'admin',name:db.auth.name};else{const u=db.users.find(x=>x.login===l&&x.password===p);if(u)session={role:'seller',name:u.name,userId:u.id,warehouses:u.warehouses}}if(session){sessionStorage.setItem('qini-session',JSON.stringify(session));render()}else el('#loginError').textContent='Укажите URL Apps Script'}}}
const navA=[['overview','⌂','Обзор'],['sellers','♙','Продавцы'],['suppliers','♧','Поставщики'],['warehouses','▣','Склады'],['accounts','▤','Счета'],['deliveries','⇄','Поставки'],['writeoffs','↘','Списания'],['stock','◫','Остатки'],['stats','◔','Статистика']],navS=[['deliveries','⇄','Поставки'],['writeoffs','↘','Списания'],['stock','◫','Остатки'],['stats','◔','Статистика']],titles={overview:['Добрый день','Сводка по вашему бизнесу'],sellers:['Продавцы','Команда и доступ к складам'],suppliers:['Поставщики','Контакты и история сотрудничества'],warehouses:['Склады','Точки хранения и счета'],accounts:['Счета','Баланс и способы оплаты'],deliveries:['Поставки','Входящие поставки и расчёты'],writeoffs:['Списания','Учет движения товаров'],stock:['Остатки','Товары на складах'],stats:['Статистика','Продажи и динамика']};
const allowed=()=>session.role==='seller'?db.warehouses.filter(w=>session.warehouses?.includes(w.id)).map(w=>w.name):db.warehouses.map(w=>w.name),filterRows=a=>session.role==='seller'?a.filter(x=>!x.warehouse||allowed().includes(x.warehouse)):a;
function render(){if(!session)return login();const nav=session.role==='admin'?navA:navS,t=titles[db.page]||titles.overview;document.querySelector('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">Q</div><div class="brand-text">qini</div><span class="role-pill">${session.role.toUpperCase()}</span></div><div class="nav-group"><div class="nav-label">Рабочий стол</div>${nav.map(x=>`<button class="nav-item ${db.page===x[0]?'active':''}" data-page="${x[0]}"><span class="nav-icon">${x[1]}</span>${x[2]}</button>`).join('')}</div><div class="sidebar-bottom"><button class="user-chip" id="profile"><div class="avatar">${session.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><div class="user-name">${esc(session.name)}</div><div class="user-caption">${session.role==='admin'?'Администратор':'Продавец'}</div></div></button><button class="nav-item logout" id="logout"><span class="nav-icon">↪</span>Выйти</button></div></aside><main class="main"><header class="topbar"><div><button class="icon-btn mobile-toggle" id="mobileMenu">☰</button><div class="eyebrow">Qini / ${t[1]}</div><h1 class="page-title">${t[0]}, ${esc(session.name.split(' ')[0])}</h1></div><div class="top-actions"><button class="icon-btn">♧<span class="dot"></span></button></div></header><div id="pageContent">${page()}</div></main></div>`;bind()}
function statsPage(){const sales=db.sales||[],total=sales.reduce((a,s)=>a+(Number(s.total)||0),0),profit=sales.reduce((a,s)=>a+(Number(s.profit)||0),0);return `<div class="kpi-grid"><div class="kpi"><div class="kpi-top">Сумма всех продаж</div><div class="kpi-value retail-amount">${money(total)}</div><div class="kpi-note muted">${sales.length} ${sales.length===1?'продажа':'продаж'}</div></div><div class="kpi"><div class="kpi-top">Общий заработок</div><div class="kpi-value profit-amount">${money(profit)}</div><div class="kpi-note muted">Продажи минус себестоимость</div></div></div><div class="card"><div class="card-head"><div><h3 class="card-title">Статистика продаж</h3><div class="card-subtitle">Каждая продажа отдельной строкой</div></div><select class="select" style="max-width:180px"><option>Все время</option><option>Сегодня</option><option>Неделя</option><option>Месяц</option></select></div>${sales.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Дата и время</th><th>Товар</th><th>Фасовка</th><th>Количество</th><th>Наценка</th><th>Сумма продажи</th><th>Заработано</th><th>Комментарий</th>${session.role==='admin'?'<th>Действия</th>':''}</tr></thead><tbody>${sales.map(s=>`<tr><td>${displayDate(s.date)}</td><td>${esc(s.productName||'')}</td><td>${esc(s.pack||'')}</td><td>${s.qty||0}</td><td>${fmtPct(s.markup)}</td><td class="retail-amount">${money(s.total)}</td><td class="profit-amount">${money(s.profit)}</td><td>${esc(s.comment||'')}</td>${session.role==='admin'?`<td><button class="action-btn danger" data-delete="sales:${s.id}">⌫</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="empty-icon">◔</div><h3 class="card-title">Продаж пока нет</h3><div class="card-subtitle">Добавьте продажу из раздела «Остатки»</div></div>'}</div>`}
function page(){if(db.page==='overview')return overview();if(db.page==='sellers')return entity('sellers','Продавцы','Новый продавец',['Имя','Логин','Телефон','Склады'],db.users.map(x=>[x.name,x.login,x.phone,x.warehouses.map(id=>db.warehouses.find(w=>w.id===id)?.name).join(', ')]));if(db.page==='suppliers')return entity('suppliers','Поставщики','Новый поставщик',['Имя','Телефон','Комментарий'],db.suppliers.map(x=>[x.name,x.phone,x.comment]));if(db.page==='warehouses')return entity('warehouses','Склады','Новый склад',['Название','Счёт','Комментарий'],db.warehouses.map(x=>[x.name,db.accounts.find(a=>a.id===x.accountId)?.name||'—',x.comment]));if(db.page==='accounts')return entity('accounts','Счета','Новый счёт',['Название','Валюта','Оплата','Баланс'],db.accounts.map(x=>[x.name,x.currency,x.payment,money(x.balance,x.currency)]));if(db.page==='deliveries')return `<div class="card"><div class="card-head"><div><h3 class="card-title">История поставок</h3><div class="card-subtitle">${db.deliveries.length} записей</div></div><button class="btn btn-primary" id="quickAdd">＋ Новая поставка</button></div>${table(filterRows(db.deliveries))}</div>`;if(db.page==='writeoffs')return `<div class="card"><div class="card-head"><div><h3 class="card-title">История списаний</h3><div class="card-subtitle">${db.writeoffs.length} записей</div></div><button class="btn btn-primary" id="quickAdd">＋ Новое списание</button></div><div class="empty"><div class="empty-icon">↘</div>${db.writeoffs.length?'Списания сохранены':'Списаний пока нет'}</div></div>`;if(db.page==='stock')return `<div class="card"><div class="card-head"><input class="input search" id="stockSearch" type="search" placeholder="Поиск товара..." autocomplete="off"><button class="btn btn-light btn-sm" id="createMenuBtn">📋 Создать меню</button></div><div class="table-wrap"><table class="table"><thead><tr></tr></thead><tbody></tbody></table></div></div>`;if(db.page==='stats')return statsPage();return '<div class="card"><div class="empty"><div class="empty-icon">◔</div><h3 class="card-title">Статистика пока пуста</h3><div class="card-subtitle">Здесь появятся продажи после подключения операций</div></div></div>'}
function overview(){const rows=filterRows(db.deliveries);return `<div class="kpi-grid"><div class="kpi"><div class="kpi-top">Остаток на счетах</div><div class="kpi-value">${money(db.accounts.reduce((a,x)=>a+x.balance,0))}</div><div class="kpi-note">↑ 8,4% к прошлому месяцу</div></div><div class="kpi"><div class="kpi-top">Товаров на складе</div><div class="kpi-value">${db.products.reduce((a,x)=>a+x.stock,0)} шт</div><div class="kpi-note">+12 за последние 7 дней</div></div><div class="kpi"><div class="kpi-top">Поставки за месяц</div><div class="kpi-value">${rows.length}</div><div class="kpi-note muted">На ${money(rows.reduce((a,d)=>a+d.total,0))}</div></div><div class="kpi"><div class="kpi-top">Текущий долг</div><div class="kpi-value">${money(rows.reduce((a,d)=>a+Math.max(d.total-d.paid,0),0))}</div><div class="kpi-note" style="color:var(--amber)">Требует внимания</div></div></div><div class="content-grid"><div class="card"><div class="card-head"><div><h3 class="card-title">Последние поставки</h3><div class="card-subtitle">Только доступные склады</div></div></div>${table(rows)}</div><div class="card"><div class="card-head"><h3 class="card-title">Популярные товары</h3></div><div class="bar-list">${db.products.slice(0,5).map((p,i)=>`<div class="bar-row"><span>${esc(p.name.split(' ')[0])}</span><div class="bar-bg"><div class="bar-fill" style="width:${90-i*18}%"></div></div><b>${90-i*18}%</b></div>`).join('')}</div></div></div>`}
function deliveryEarned(d){return (db.sales||[]).filter(s=>String(s.deliveryId)===String(d.id)).reduce((a,s)=>a+(Number(s.profit)||0),0)}
