function entity(type,title,add,heads,rows){const list={sellers:db.users,suppliers:db.suppliers,warehouses:db.warehouses,accounts:db.accounts}[type];return `<div class="card"><div class="card-head"><input class="input search" placeholder="Поиск ${title.toLowerCase()}..."><button class="btn btn-primary" id="quickAdd">＋ ${add}</button></div><div class="table-wrap"><table class="table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}<th>Действия</th></tr></thead><tbody>${rows.map((r,i)=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}<td><button class="action-btn edit" data-edit="${type}:${list[i].id}">✎</button><button class="action-btn danger" data-delete="${type}:${list[i].id}">⌫</button></td></tr>`).join('')}</tbody></table></div></div>`}
function fields(type,old){const f=type==='accounts'?[['name','Название счёта'],['initial','Изначальная сумма']]:type==='sellers'?[['name','Имя продавца'],['phone','Телефон'],['address','Адрес'],['login','Логин'],['password','Пароль']]:type==='warehouses'?[['name','Название склада'],['comment','Комментарий']]:[['name',type==='suppliers'?'Имя поставщика':'Название'],['phone','Телефон'],['comment','Комментарий']];return f.map(([k,l])=>`<div class="field ${['comment','address'].includes(k)?'full':''}"><label class="label">${l}</label>${['comment','address'].includes(k)?`<textarea class="textarea" name="${k}">${esc(old[k]||'')}</textarea>`:`<input class="input" name="${k}" type="${k==='password'?'password':k==='initial'?'number':'text'}" autocomplete="${k==='password'?'new-password':'off'}" value="${k==='password'?'':esc(old[k]||'')}" placeholder="${k==='password'&&old.id?'Оставьте пустым, чтобы не менять':''}" ${['name','login'].includes(k)?'required':''}>`}</div>`).join('')}
function form(type,id){const list={sellers:db.users,suppliers:db.suppliers,warehouses:db.warehouses,accounts:db.accounts}[type]||[],old=list.find(x=>x.id===id)||{};return `<form class="form" id="entityForm" data-type="${type}" data-id="${id||''}"><div class="form-grid">${fields(type,old)}${type==='accounts'?`<div class="field"><label class="label">Валюта</label><select class="select" name="currency">${Object.entries(CURRENCY).map(([k,v])=>`<option value="${k}" ${old.currency===k?'selected':''}>${k} — ${v}</option>`).join('')}</select></div><div class="field"><label class="label">Вариант оплаты</label><select class="select" name="payment"><option ${old.payment==='Наличный'?'selected':''}>Наличный</option><option ${old.payment==='Безналичный'?'selected':''}>Безналичный</option></select></div>`:''}${type==='warehouses'?`<div class="field"><label class="label">Счёт</label><select class="select" name="accountId">${db.accounts.map(a=>`<option value="${a.id}" ${a.id===old.accountId?'selected':''}>${a.name}</option>`).join('')}</select></div>`:''}${type==='sellers'?`<div class="field full"><label class="label">Доступные склады</label><select class="select" name="warehouses" multiple>${db.warehouses.map(w=>`<option value="${w.id}" ${old.warehouses?.includes(w.id)?'selected':''}>${w.name}</option>`).join('')}</select></div>`:''}</div><div class="modal-foot"><button type="button" class="btn btn-light" id="closeModal">Отмена</button><button class="btn btn-primary">Сохранить</button></div></form>`}
function nowLocal(){const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
function inputDate(value){if(!value)return nowLocal();if(value.includes('T'))return value.slice(0,16);const m=value.match(/(\d{2})\.(\d{2})\.(\d{4})\s+(\d{2}):(\d{2})/);return m?`${m[3]}-${m[2]}-${m[1]}T${m[4]}:${m[5]}`:nowLocal()}
function packOptionsHtml(packs,currentPack,custom){
  return `<option value="" disabled hidden ${!currentPack&&!custom?'selected':''}></option>`+
    packs.map(p=>`<option ${p===currentPack?'selected':''}>${esc(p)}</option>`).join('')+
    `<option value="__custom__" ${custom?'selected':''}>＋ Фасовка</option>`;
}
function lineHtml(item={},kind='delivery'){const cost=(item.qty||0)*(item.cost||0),retail=item.retailTotal||cost*(1+(item.markup||30)/100),packs=catalogPacks(item.name),custom=item.pack&&!packs.includes(item.pack);return `<div class="line-item item-line"><input class="input" name="itemName" list="qini-products" value="${esc(item.name||'')}" placeholder="Название товара"><select class="select" name="pack">${packOptionsHtml(packs,item.pack,custom)}</select><input class="input pack-custom" name="packCustom" value="${custom?esc(item.pack):''}" placeholder="Введите фасовку" style="display:${custom?'block':'none'}"><input class="input" name="qty" type="number" value="${item.qty||''}" placeholder="Количество"><input class="input" name="cost" type="number" value="${item.cost||''}" placeholder="Цена / себестоимость"><input class="input calculated-cost" name="costTotal" value="${cost||0}" readonly><input class="input markup-field" name="markup" type="number" value="${item.markup||30}" placeholder="Наценка %"><input class="input calculated-retail" name="retailTotal" type="number" value="${retail||0}" placeholder="Сумма с наценкой"><button type="button" class="remove-line">×</button></div>`}
function productDatalist(){return `<datalist id="qini-products">${catalogNames().map(n=>`<option value="${esc(n)}"></option>`).join('')}</datalist>`}
function deliveryForm(id){const old=db.deliveries.find(x=>x.id===id)||{},items=old.items?.length?old.items:[{}];return `<form class="form" id="deliveryForm" data-id="${id||''}">${productDatalist()}<div class="form-grid"><div class="field"><label class="label">Дата и время</label><input class="input" name="date" type="datetime-local" value="${inputDate(old.date)}" required></div><div class="field"><label class="label">Поставщик</label><select class="select" name="supplier">${db.suppliers.map(x=>`<option ${x.name===old.supplier?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label class="label">Склад</label><select class="select" name="warehouse">${allowed().map(x=>`<option ${x===old.warehouse?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label class="label">Счёт</label><select class="select" name="account">${db.accounts.map(x=>`<option ${x.name===old.account?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label class="label">Оплаченная сумма</label><input class="input" name="paid" type="number" min="0" value="${old.paid||''}" placeholder="Можно оставить пустым"></div><div class="field"><label class="label">Комментарий</label><input class="input" name="comment" value="${esc(old.comment||'')}" placeholder="Необязательно"></div><div class="field full"><label class="label">Товары в поставке</label><div class="line-items" id="deliveryLines">${items.map(i=>lineHtml(i)).join('')}</div><button type="button" class="add-line" id="addDeliveryLine">＋ Добавить ещё товар</button></div></div><div class="summary-row"><div><div class="summary-label">Сумма поставки</div><div class="summary-value" id="deliveryTotal">${money(old.total||0)}</div></div><div><div class="summary-label">Сумма с наценкой</div><div class="summary-value retail-amount" id="deliveryRetailTotal">${money(items.reduce((a,i)=>a+(i.retailTotal||((i.qty||0)*(i.cost||0)*(1+(i.markup||30)/100))),0))}</div></div></div><div class="modal-foot"><button type="button" class="btn btn-light" id="closeModal">Отмена</button><button class="btn btn-primary">${id?'Сохранить изменения':'Добавить поставку'}</button></div></form>`}
function writeoffForm(id){const old=db.writeoffs.find(x=>x.id===id)||{},items=old.items?.length?old.items:[{}];return `<form class="form" id="writeoffForm" data-id="${id||''}">${productDatalist()}<div class="form-grid"><div class="field"><label class="label">Дата и время</label><input class="input" name="date" type="datetime-local" value="${inputDate(old.date)}" required></div><div class="field"><label class="label">Склад</label><select class="select" name="warehouse">${allowed().map(x=>`<option ${x===old.warehouse?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label class="label">Счёт зачисления</label><select class="select" name="account">${db.accounts.map(x=>`<option ${x.name===old.account?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label class="label">Комментарий</label><input class="input" name="comment" value="${esc(old.comment||'')}" placeholder="Необязательно"></div><div class="field full"><label class="label">Товары к списанию</label><div class="line-items" id="writeoffLines">${items.map(i=>lineHtml(i,'writeoff')).join('')}</div><button type="button" class="add-line" id="addWriteoffLine">＋ Добавить ещё товар</button></div></div><div class="summary-row"><div><div class="summary-label">Сумма списания</div><div class="summary-value" id="writeoffTotal">${money(old.total||0)}</div></div><div><div class="summary-label">Цена с наценкой</div><div class="summary-value retail-amount" id="writeoffRetailTotal">${money(items.reduce((a,i)=>a+(i.retailTotal||((i.qty||0)*(i.cost||0)*(1+(i.markup||30)/100))),0))}</div></div></div><div class="modal-foot"><button type="button" class="btn btn-light" id="closeModal">Отмена</button><button class="btn btn-primary">${id?'Сохранить изменения':'Добавить списание'}</button></div></form>`}
function modal(type,id){if(type==='delivery')return deliveryForm(id);if(type==='writeoff')return writeoffForm(id);if(type==='profile')return `<form class="form" id="profileForm"><div class="form-grid"><div class="field"><label class="label">Имя</label><input class="input" name="name" value="${esc(db.auth.name)}" required></div><div class="field"><label class="label">Телефон</label><input class="input" name="phone" value="${esc(db.auth.phone||'')}"></div><div class="field"><label class="label">Логин</label><input class="input" name="login" value="${esc(db.auth.login)}" required></div><div class="field"><label class="label">Новый пароль</label><input class="input" name="password" type="password" autocomplete="new-password"></div></div><div class="modal-foot"><button type="button" class="btn btn-light" id="closeModal">Отмена</button><button class="btn btn-primary">Сохранить</button></div></form>`;return form(type,id)}
function collectItems(form){return [...form.querySelectorAll('.item-line')].map(row=>{const qty=+(row.querySelector('[name=qty]')?.value||0),cost=+(row.querySelector('[name=cost]')?.value||0),retail=+(row.querySelector('[name=retailTotal]')?.value||0),typedMarkup=+(row.querySelector('[name=markup]')?.value||30),packSelect=row.querySelector('[name=pack]')?.value||'',pack=packSelect==='__custom__'?(row.querySelector('[name=packCustom]')?.value||''):packSelect;return {name:row.querySelector('[name=itemName]')?.value||'',pack,qty,cost,markup:retail&&qty&&cost?((retail/(qty*cost))-1)*100:typedMarkup,retailTotal:retail}}).filter(x=>x.name||x.qty)}
function bindLineRemove(){document.querySelectorAll('.remove-line').forEach(b=>b.onclick=()=>{if(document.querySelectorAll('.item-line').length>1)b.closest('.item-line').remove()})}
function openModal(type,id){const title=type==='profile'?'Мой профиль':id?'Редактировать запись':({delivery:'Новая поставка',writeoff:'Новое списание',sellers:'Новый продавец',suppliers:'Новый поставщик',warehouses:'Новый склад',accounts:'Новый счёт'}[type]||'Добавить');document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><div><h2 class="modal-title">${title}</h2><div class="modal-desc">Изменения сохраняются в Google Sheets</div></div><button class="close" id="x">×</button></div>${modal(type,id)}</div></div>`);el('#x').onclick=()=>el('#modal').remove();el('#closeModal').onclick=()=>el('#modal').remove();if(type==='delivery'||type==='writeoff'){const formEl=el(type==='delivery'?'#deliveryForm':'#writeoffForm');el(type==='delivery'?'#addDeliveryLine':'#addWriteoffLine').onclick=()=>{const target=el(type==='delivery'?'#deliveryLines':'#writeoffLines');target.insertAdjacentHTML('beforeend',lineHtml({},type));bindLineRemove()};bindLineRemove();formEl.addEventListener('input',()=>{const total=collectItems(formEl).reduce((a,x)=>a+x.qty*x.cost,0);const out=el(type==='delivery'?'#deliveryTotal':'#writeoffTotal');if(out)out.textContent=money(total)});formEl.onsubmit=async e=>{e.preventDefault();const submit=e.submitter;if(submit)submit.disabled=true;const f=new FormData(e.target),items=collectItems(e.target),total=items.reduce((a,x)=>a+x.qty*x.cost,0),supplier=f.get('supplier'),warehouse=f.get('warehouse'),account=f.get('account'),data={id:id||undefined,date:f.get('date'),warehouse,account,paid:+f.get('paid')||0,total,comment:f.get('comment'),items:JSON.stringify(items)};if(type==='delivery'){data.supplier=supplier;data.status=data.paid>=data.total?'paid':'due';data.supplierId=db.suppliers.find(x=>x.name===supplier)?.id||'';data.warehouseId=db.warehouses.find(x=>x.name===warehouse)?.id||'';data.accountId=db.accounts.find(x=>x.name===account)?.id||''}else{data.warehouseId=db.warehouses.find(x=>x.name===warehouse)?.id||'';data.accountId=db.accounts.find(x=>x.name===account)?.id||''}const response=await api(id?'update':'create',type==='delivery'?'Deliveries':'Writeoffs',data);if(API_URL&&!response.ok){if(submit)submit.disabled=false;toast('Ошибка сохранения: '+(response.error||'API'));return}items.forEach(i=>catalogAdd(i.name,i.pack));const list=type==='delivery'?db.deliveries:db.writeoffs,local={...data,items,date:data.date};if(id){const old=list.find(x=>x.id===id);Object.assign(old,local)}else{const newId=(response&&response.data&&response.data.id)||((type==='delivery'?'d':'wo')+Date.now());list.unshift({...local,id:newId})}save();el('#modal').remove();render();if(API_URL){try{await sync()}catch(e){}}toast(type==='delivery'?'Поставка сохранена':'Списание сохранено')}}else if(type==='profile')el('#profileForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);db.auth.name=f.get('name');db.auth.phone=f.get('phone');db.auth.login=f.get('login');if(f.get('password'))db.auth.password=f.get('password');session.name=db.auth.name;sessionStorage.setItem('qini-session',JSON.stringify(session));save();el('#modal').remove();render();toast('Профиль обновлён')};else{const f=el('#entityForm');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const submit=e.submitter;if(submit)submit.disabled=true;const data=Object.fromEntries(new FormData(f)),t=f.dataset.type,id=f.dataset.id,list={sellers:db.users,suppliers:db.suppliers,warehouses:db.warehouses,accounts:db.accounts}[t];let selected=[];if(t==='sellers'){selected=new FormData(f).getAll('warehouses');data.warehouseIds=JSON.stringify(selected)}if(t==='accounts')Object.assign(data,{currency:data.currency||'GEL',payment:data.payment||'Наличный',balance:+data.initial||0});const payload={...data,id:id||undefined};const response=await api(id?'update':'create',t==='sellers'?'Sellers':t[0].toUpperCase()+t.slice(1),payload);if(API_URL&&!response.ok){if(submit)submit.disabled=false;toast('Ошибка сохранения: '+(response.error||'API'));return}delete data.warehouseIds;if(t==='sellers')data.warehouses=selected;if(id){const old=list.find(x=>x.id===id);if(!data.password)delete data.password;Object.assign(old,data)}else{data.id=(response&&response.data&&response.data.id)||data.id||(t[0]+Date.now());list.push(data)}save();el('#modal').remove();render();if(API_URL){try{await sync()}catch(e){}}toast(id?'Изменения сохранены':'Запись добавлена')}}}
function confirmInApp(message){return new Promise(resolve=>{document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="confirmModal"><div class="confirm-modal"><div class="confirm-icon">!</div><h3>Удалить запись?</h3><p>${message}</p><div class="confirm-actions"><button class="btn btn-light" id="cancelConfirm">Отмена</button><button class="btn btn-danger" id="acceptConfirm">Удалить</button></div></div></div>`);el('#cancelConfirm').onclick=()=>{el('#confirmModal').remove();resolve(false)};el('#acceptConfirm').onclick=()=>{el('#confirmModal').remove();resolve(true)}})}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{db.page=b.dataset.page;stockFilter='';save();render()});document.querySelectorAll('#quickAdd').forEach(b=>b.onclick=()=>openModal(db.page==='deliveries'?'delivery':db.page==='writeoffs'?'writeoff':db.page));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const [t,id]=b.dataset.edit.split(':');openModal(t==='deliveries'?'delivery':t==='writeoffs'?'writeoff':t,id)});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{const [t,id]=b.dataset.delete.split(':');if(t==='sales'||t==='writeoffs'){await deleteRecord(t,id);return}if(await confirmInApp(t==='deliveries'?'Удалить поставку и все продажи, сделанные из её партий?':'После удаления запись нельзя будет восстановить.')){const list={sellers:db.users,suppliers:db.suppliers,warehouses:db.warehouses,accounts:db.accounts,deliveries:db.deliveries,writeoffs:db.writeoffs}[t],i=list.findIndex(x=>x.id===id),entity=t==='sellers'?'Sellers':t[0].toUpperCase()+t.slice(1);const response=await api('delete',entity,{id});if(API_URL&&!response.ok){toast('Ошибка удаления: '+(response.error||'API'));return}if(t==='deliveries'){db.sales=(db.sales||[]).filter(s=>String(s.deliveryId)!==String(id))}if(i>=0)list.splice(i,1);save();render();if(API_URL){try{await sync()}catch(e){}}toast('Запись удалена')}});el('#profile')?.addEventListener('click',()=>session.role==='admin'?openModal('profile'):toast('Профиль изменяет администратор'));el('#logout')?.addEventListener('click',()=>{session=null;sessionStorage.removeItem('qini-session');render()});el('#mobileMenu')?.addEventListener('click',()=>el('#sidebar').classList.toggle('open'))}
async function sync(){if(!API_URL||!session?.token)return;try{const r=await fetch(`${API_URL}?action=bootstrap&token=${encodeURIComponent(session.token)}`),text=await r.text(),p=JSON.parse(text);if(p.ok){const x=normalizeSheetData(p.data);db.accounts=x.Accounts||db.accounts;db.warehouses=x.Warehouses||db.warehouses;db.suppliers=x.Suppliers||db.suppliers;db.users=x.Sellers||db.users;const current=db.users.find(u=>String(u.id)===String(session.userId)||String(u.login)===String(session.login));if(session.role==='seller'&&current){session.userId=current.id;session.warehouses=current.warehouses||[];sessionStorage.setItem('qini-session',JSON.stringify(session))}db.sales=x.Sales||db.sales;db.deliveries=x.Deliveries||db.deliveries;db.writeoffs=x.Writeoffs||db.writeoffs;(db.deliveries||[]).forEach(d=>(d.items||[]).forEach(i=>catalogAdd(i.name,i.pack)));(db.writeoffs||[]).forEach(w=>(w.items||[]).forEach(i=>catalogAdd(i.name,i.pack)));(db.sales||[]).forEach(s=>catalogAdd(s.productName,s.pack));db.products=inventoryFromData(x);save();render()}}catch(e){console.warn('sync unavailable',e)}}
function stockSales(p){return (db.sales||[]).filter(s=>s.productName===p.name&&String(s.pack||'')===String(p.pack||'')&&(!p.warehouse||s.warehouse===p.warehouse)).reduce((a,s)=>({qty:a.qty+(+s.qty||0),total:a.total+(+s.total||0),profit:a.profit+(+s.profit||0)}),{qty:0,total:0,profit:0})}
function decorateStock(){
  const table=document.querySelector('.table');if(!table)return;
  const tr=table.querySelector('thead tr');
  const labels=[
    {t:'Товар',title:'Товар'},
    {t:'Склад',title:'Склад'},
    {t:'Партия',title:'Партия — дата и поставщик поставки'},
    {t:'Ост.',title:'Остаток на складе'},
    {t:'Себес.',title:'Себестоимость за единицу'},
    {t:'Закуп',title:'Сумма по себестоимости (себестоимость × остаток)'},
    {t:'Нц.',title:'Наценка, %'},
    {t:'Цена',title:'Цена с наценкой за единицу'},
    {t:'Итого',title:'Итого с наценкой (цена × остаток)'},
    {t:'',title:''}
  ];
  tr.innerHTML=labels.map(x=>`<th title="${x.title}">${x.t}</th>`).join('');
  const q=stockFilter.trim().toLowerCase();
  const list=q?db.products.filter(p=>(p.name||'').toLowerCase().includes(q)||(p.pack||'').toLowerCase().includes(q)||(p.warehouse||'').toLowerCase().includes(q)||(p.supplier||'').toLowerCase().includes(q)):db.products;
  const tbody=table.querySelector('tbody');
  if(!list.length){tbody.innerHTML=`<tr><td colspan="10"><div class="empty"><div class="empty-icon">◫</div><div class="card-subtitle">${q?'Ничего не найдено':'Остатков пока нет'}</div></div></td></tr>`;return}
  tbody.innerHTML=list.map(p=>{
    const idx=db.products.indexOf(p);
    const unit=p.cost*(1+p.markup/100);
    const deliveryFull=p.deliveryDate?`${displayDate(p.deliveryDate)}${p.supplier?' · '+p.supplier:''}`:'—';
    const deliveryShort=p.deliveryDate?displayDate(p.deliveryDate):'—';
    return `<tr><td>${esc(p.name)} <span style="color:var(--muted);font-weight:400">${esc(p.pack)}</span></td><td>${esc(p.warehouse||'—')}</td><td title="${esc(deliveryFull)}" style="white-space:nowrap">${esc(deliveryShort)}</td><td class="amount">${p.stock} шт</td><td class="cost-amount">${money(p.cost)}</td><td class="cost-amount">${money(p.cost*p.stock)}</td><td><input class="input preview-markup" type="number" min="0" value="${p.markup}" style="width:70px"> %</td><td class="retail-amount retail-unit">${money(unit)}</td><td class="retail-amount retail-total">${money(unit*p.stock)}</td><td><button class="btn btn-primary btn-sm sell-stock" data-stock-index="${idx}">Продать</button></td></tr>`;
  }).join('');
  tbody.querySelectorAll('.preview-markup').forEach((input,k)=>{
    const p=list[k];if(!p)return;
    input.addEventListener('input',()=>{
      const markup=+input.value||0,unit=p.cost*(1+markup/100);
      const row=input.closest('tr');
      const ru=row.querySelector('.retail-unit'),rt=row.querySelector('.retail-total');
      if(ru)ru.textContent=money(unit);
      if(rt)rt.textContent=money(unit*p.stock);
    });
  });
  tbody.querySelectorAll('.sell-stock').forEach(b=>b.onclick=()=>openSaleModal(db.products[+b.dataset.stockIndex]));
}
