document.addEventListener('input',e=>{const form=e.target.closest('#deliveryForm,#writeoffForm');if(!form)return;const row=e.target.closest('.item-line');if(row&&e.target.name==='itemName'){const name=e.target.value,select=row.querySelector('[name=pack]');if(select){const current=select.value;const packs=catalogPacks(name);const custom=current==='__custom__';select.innerHTML=packOptionsHtml(packs,current,custom);select.value=current||''}}if(row&&e.target.name==='retailTotal'){const qty=+(row.querySelector('[name=qty]')?.value||0),cost=+(row.querySelector('[name=cost]')?.value||0);if(qty&&cost)row.querySelector('[name=markup]').value=(((+e.target.value/(qty*cost))-1)*100).toFixed(2)}else form.querySelectorAll('.item-line').forEach(r=>{const qty=+(r.querySelector('[name=qty]')?.value||0),cost=+(r.querySelector('[name=cost]')?.value||0),markup=+(r.querySelector('[name=markup]')?.value||30),base=qty*cost,c=r.querySelector('[name=costTotal]'),ret=r.querySelector('[name=retailTotal]');if(c)c.value=base.toFixed(2);if(ret)ret.value=(base*(1+markup/100)).toFixed(2)});const items=collectItems(form),base=items.reduce((a,x)=>a+x.qty*x.cost,0),retail=items.reduce((a,x)=>a+(x.retailTotal||x.qty*x.cost*(1+x.markup/100)),0),out=form.querySelector('#deliveryTotal,#writeoffTotal'),retailOut=form.querySelector('#deliveryRetailTotal,#writeoffRetailTotal');if(out)out.textContent=money(base);if(retailOut)retailOut.textContent=money(retail)});
document.addEventListener('change',e=>{if(e.target.name!=='pack')return;const custom=e.target.value==='__custom__',row=e.target.closest('.item-line'),input=row?.querySelector('[name=packCustom]');if(input){input.style.display=custom?'block':'none';if(custom)input.focus()}});
document.addEventListener('change',e=>{if(e.target.name!=='pack')return;const form=e.target.closest('#writeoffForm'),row=e.target.closest('.item-line');if(!form||!row)return;const item=sourceItem(row.querySelector('[name=itemName]')?.value,row.querySelector('[name=pack]')?.value,form.querySelector('[name=warehouse]')?.value);if(item){row.querySelector('[name=cost]').value=item.cost||0;row.querySelector('[name=markup]').value=item.markup??0;row.querySelector('[name=cost]').dispatchEvent(new Event('input',{bubbles:true}))}});
